      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      font-size: 1rem;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 16px 34px rgba(6, 182, 212, 0.2);
      transition: transform 160ms ease, filter 160ms ease;
