    button:hover {
      transform: translateY(-2px);
      filter: brightness(1.08);
    }

    .result {
      color: var(--subtle);
      min-height: 1.5em;
      margin: 0;
    }

    @media (max-width: 680px) {
      body {
        padding: 20px 12px;
      }

      .choices {
        grid-template-columns: 1fr;
      }

      .form-field {
        padding: 22px;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const questions = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every answer that names a language used to write computer programs.",
        choices: ["Python", "HTML", "JavaScript", "C++"]
      },
      {
        id: "typed-languages",
        prompt: "Which languages are commonly described as statically typed?",
        choices: ["TypeScript", "Java", "Ruby", "Go"]
      },
      {
        id: "web-languages",
        prompt: "Which languages can run directly in modern web browsers?",
        choices: ["JavaScript", "WebAssembly text format", "SQL", "Python"]
      }
    ];

    function App() {
      return `
        <section class="quiz-shell" aria-labelledby="quiz-title">
          ${QuizHeader()}
          ${QuizForm({ questions })}
