            <button type="submit">Submit answers</button>
            <p class="result" id="result" role="status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    function QuestionField(question, index) {
      const helpId = question.helpText ? `${question.id}-help` : "";

      return `
        <div class="form-field">
          <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
            <legend>${index + 1}. ${question.prompt}</legend>
            ${question.helpText ? `<p class="help-text" id="${helpId}">${question.helpText}</p>` : ""}
            <div class="choices">
              ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
            </div>
          </fieldset>
        </div>
      `;
