        padding: 22px;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const questions = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every answer that names a language used to write computer programs.",
        choices: ["Python", "HTML", "JavaScript", "C++"]
      },
      {
        id: "typed-languages",
        prompt: "Which languages are commonly described as statically typed?",
        choices: ["TypeScript", "Java", "Ruby", "Go"]
      },
      {
        id: "web-languages",
        prompt: "Which languages can run directly in modern web browsers?",
        choices: ["JavaScript", "WebAssembly text format", "SQL", "Python"]
      }
    ];

    function App() {
      return `
        <section class="quiz-shell" aria-labelledby="quiz-title">
          ${QuizHeader()}
          ${QuizForm({ questions })}
        </section>
      `;
    }

    function QuizHeader() {
      return `
        <header class="hero">
          <p class="eyebrow">Multiple selection quiz</p>
          <h1 id="quiz-title">Computer Languages</h1>
          <p class="intro">
            Test your language knowledge. Some questions may have more than one correct answer, so choose all answers that apply.
          </p>
        </header>
      `;
    }

    function QuizForm({ questions }) {
      return `
        <form id="quiz-form">
          ${questions.map(QuestionField).join("")}
          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="result" role="status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    function QuestionField(question, index) {
      const helpId = question.helpText ? `${question.id}-help` : "";

      return `
        <div class="form-field">
          <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
            <legend>${index + 1}. ${question.prompt}</legend>
            ${question.helpText ? `<p class="help-text" id="${helpId}">${question.helpText}</p>` : ""}
            <div class="choices">
              ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
            </div>
          </fieldset>
        </div>
      `;
    }

    function Choice({ questionId, choice }) {
      const value = choice.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
      const id = `${questionId}-${value}`;

      return `
        <label class="choice" for="${id}">
          <input type="checkbox" id="${id}" name="${questionId}" value="${choice}">
          <span>${choice}</span>
        </label>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = document.querySelectorAll("input[type='checkbox']:checked").length;
      const result = document.getElementById("result");
      result.textContent = selectedCount
        ? `Submitted ${selectedCount} selected answer${selectedCount === 1 ? "" : "s"}.`
        : "Select at least one answer before submitting.";
    });
  </script>
</body>
</html>
